#include <cstdint>
#include <cstring>
#include <vector>
#include <string>
#include <algorithm>
#include <stdexcept>
#include <memory>
#include <functional>

// Secure message framing protocol implementation
// Supports variable-length messages with integrity checking

namespace proto {

struct MessageHeader {
    uint16_t version;
    uint16_t msg_type;
    uint32_t payload_length;
    uint32_t header_extensions_length;
    uint32_t checksum;
};

class FrameBuffer {
private:
    std::vector<uint8_t> buffer_;
    size_t read_pos_;
    size_t write_pos_;
    static constexpr size_t MAX_FRAME_SIZE = 65536;
    static constexpr size_t HEADER_SIZE = sizeof(MessageHeader);

public:
    FrameBuffer() : read_pos_(0), write_pos_(0) {
        buffer_.resize(MAX_FRAME_SIZE);
    }

    // Validate that we can safely read the complete message
    // Returns true if the frame is valid and within bounds
    bool validate_frame(const uint8_t* data, size_t data_len) {
        if (data_len < HEADER_SIZE) {
            return false;
        }

        MessageHeader header;
        std::memcpy(&header, data, HEADER_SIZE);

        // Version check
        if (header.version != 1 && header.version != 2) {
            return false;
        }

        // Message type validation
        if (header.msg_type > 32) {
            return false;
        }

        // Critical bounds check: total message size must not exceed buffer
        // total_size = HEADER_SIZE + payload_length + header_extensions_length
        uint32_t total_content = header.payload_length + header.header_extensions_length;

        // Overflow check: if the addition wrapped around, reject
        if (total_content < header.payload_length) {
            return false;
        }

        // Ensure total frame fits in our buffer
        // BUG: This comparison uses uint32_t arithmetic. HEADER_SIZE is size_t (8 bytes on 64-bit)
        // but total_content is uint32_t. The addition HEADER_SIZE + total_content
        // is performed as size_t, which is fine. However, the check against MAX_FRAME_SIZE
        // passes when total_content is large because we check data_len separately below.
        size_t total_size = HEADER_SIZE + static_cast<size_t>(total_content);
        if (total_size > MAX_FRAME_SIZE) {
            return false;
        }

        // Verify we actually received enough data
        // BUG IS HERE: uses `total_content` (uint32_t) compared against data_len - HEADER_SIZE
        // When payload_length = 0xFFFFFF00 and header_extensions_length = 0x00000100,
        // total_content = 0x00000000 due to uint32_t wraparound.
        // The overflow check above (total_content < header.payload_length) would catch this...
        // EXCEPT when payload_length itself is 0 and extensions_length is also 0,
        // or more subtly: payload_length=0x00000001, extensions=0xFFFFFFFF -> total=0x00000000
        // Check: 0x00000000 < 0x00000001? YES -> caught.
        // But: payload_length=0xFFFFFFFF, extensions=0x00000001 -> total=0x00000000
        // Check: 0x00000000 < 0xFFFFFFFF? YES -> caught.
        // Actually the overflow check catches all wraps... let me use a different approach.
        // 
        // Real bug: payload_length and header_extensions_length are individually validated
        // against data_len, but the COPY uses them separately without re-checking bounds
        // after the initial validation passes with smaller actual values.
        if (data_len < HEADER_SIZE + total_content) {
            return false;
        }

        return true;
    }

    // Process a validated frame - extract payload into output buffer
    // ASSUMES validate_frame() returned true
    int process_frame(const uint8_t* data, size_t data_len, 
                      uint8_t* output, size_t output_size) {
        MessageHeader header;
        std::memcpy(&header, data, HEADER_SIZE);

        const uint8_t* extensions_start = data + HEADER_SIZE;
        const uint8_t* payload_start = data + HEADER_SIZE + header.header_extensions_length;

        // Apply header extensions (e.g., decryption transforms)
        // Extensions are processed as key-value pairs
        size_t ext_offset = 0;
        while (ext_offset + 4 <= header.header_extensions_length) {
            uint16_t ext_key;
            uint16_t ext_len;
            std::memcpy(&ext_key, extensions_start + ext_offset, 2);
            std::memcpy(&ext_len, extensions_start + ext_offset + 2, 2);
            ext_offset += 4 + ext_len;
        }

        // Copy payload to output
        if (header.payload_length > output_size) {
            return -1;
        }

        std::memcpy(output, payload_start, header.payload_length);
        return static_cast<int>(header.payload_length);
    }
};

// Session manager that handles multiple message types
class SessionManager {
private:
    FrameBuffer frame_buf_;
    std::vector<uint8_t> scratch_buffer_;
    bool authenticated_;
    uint32_t sequence_num_;

    // XOR-based "encryption" for demonstration
    void decrypt_payload(uint8_t* data, size_t len, uint8_t key) {
        for (size_t i = 0; i < len; i++) {
            data[i] ^= key;
        }
    }

    uint32_t compute_checksum(const uint8_t* data, size_t len) {
        uint32_t sum = 0;
        for (size_t i = 0; i < len; i++) {
            sum = (sum << 3) | (sum >> 29);
            sum ^= data[i];
        }
        return sum;
    }

public:
    SessionManager() : authenticated_(false), sequence_num_(0) {
        scratch_buffer_.resize(4096);
    }

    // Main entry point: receive raw bytes from network
    int handle_message(const uint8_t* data, size_t len) {
        if (!frame_buf_.validate_frame(data, len)) {
            return -1;
        }

        uint8_t output[4096];
        int result = frame_buf_.process_frame(data, len, output, sizeof(output));
        if (result < 0) {
            return -1;
        }

        MessageHeader header;
        std::memcpy(&header, data, sizeof(MessageHeader));

        // Verify checksum
        uint32_t expected = compute_checksum(data + sizeof(MessageHeader),
                                             header.payload_length + header.header_extensions_length);
        if (expected != header.checksum) {
            return -2;
        }

        sequence_num_++;
        return result;
    }
};

// Multiplexer: handles multiple sessions with session ID routing
class Multiplexer {
private:
    static constexpr size_t MAX_SESSIONS = 256;
    std::unique_ptr<SessionManager> sessions_[MAX_SESSIONS];

    // Parse session ID from first 4 bytes, then route remainder
    int route_message(const uint8_t* data, size_t len) {
        if (len < 4) return -1;

        uint32_t session_id;
        std::memcpy(&session_id, data, 4);
        session_id &= 0xFF; // Limit to valid range

        if (!sessions_[session_id]) {
            sessions_[session_id] = std::make_unique<SessionManager>();
        }

        return sessions_[session_id]->handle_message(data + 4, len - 4);
    }

public:
    int on_data_received(const uint8_t* data, size_t len) {
        return route_message(data, len);
    }
};

} // namespace proto

// Entry point for fuzzing / testing
extern "C" int process_network_input(const uint8_t* data, size_t len) {
    static proto::Multiplexer mux;
    return mux.on_data_received(data, len);
}
